fn search_insert(xs: &Vec<i32>, target: i32) -> usize {
    let mut lo: usize = 0;
    let mut hi: usize = xs.len();

    // Invariant: the insertion position is in [lo, hi]
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if xs[mid] < target {
            // target must go strictly after mid
            lo = mid + 1;
        } else {
            // xs[mid] >= target, so target could go at mid or before
            hi = mid;
        }
    }

    lo
}

